fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x101014);
    let cw: i32 = (w - 16) / 7;
    let ch: i32 = (h - 60) / 5;
    let heads = [83, 77, 84, 87, 84, 70, 83];
    let mut c: i32 = 0;
    while c < 7 {
        host::display::draw_char(8 + c * cw + cw / 2 - 8, 10, heads[c], 0x808080, 2);
        c = c + 1;
    }
    let today: i32 = (t / 120) % 31 + 1;
    let mut cell: i32 = 0;
    while cell < 35 {
        let day: i32 = cell - 2;
        let col: i32 = cell % 7;
        let row: i32 = cell / 7;
        let x: i32 = 8 + col * cw;
        let y: i32 = 34 + row * ch;
        if day >= 1 && day <= 31 {
            if day == today {
                host::display::fill_rect(x + 1, y + 1, cw - 2, ch - 2, 0xffffff);
                host::display::draw_number(x + 6, y + 6, day, 0x000000, 2);
            } else {
                host::display::fill_rect(x + 1, y + 1, cw - 2, ch - 2, 0x1c1c24);
                host::display::draw_number(x + 6, y + 6, day, 0xc0c0c0, 2);
            }
        }
        cell = cell + 1;
    }
    host::display::present();
}
